// Reads the demo's translation unit: the YAML format complier's CLI loads (`translate` with
// tools, schema, assumption, rules and fallback, plus `hidden` reads), checked the same way
// before any CEL runs. Every error carries the line and column it is about.
//
// The demo has no `service:` line: it is bound to Notion's tool list (packages/notion/tools.ts,
// generated by `complier gen notion`) and the tools reviewed there as read-only.

import { isMap, isScalar, isSeq, LineCounter, parseDocument, visit, type Node } from "yaml";
import { notionSchemaHashes } from "../../../../packages/notion/tools.ts";
import { parseType, type Ty } from "./translation.ts";

export type At = { line: number; col: number };
export type UnitError = At & { path: string; message: string };

export type Field = { name: string; type: string; ty: Ty };
export type Rule = { name: string; when: string; emit: string; at: At };
export type Unit = {
  tools: string[];
  schema: Field[];
  assumption: string;
  assumptionAt?: At;
  rules: Rule[];
  fallback: string;
  hidden: string[];
  timeoutMs: number;
  unroll: number;
};

export const NOTION_TOOLS = new Set(Object.keys(notionSchemaHashes));
// Reviewed as side-effect free in Notion's service metadata; only these may be hidden.
export const NOTION_READ_ONLY = new Set([
  "notion-fetch",
  "notion-search",
  "notion-get-comments",
  "notion-get-users",
  "notion-get-self",
  "notion-get-teams",
  "notion-list-private-pages",
  "notion-list-shared-pages",
  "notion-list-favorite-pages",
  "notion-list-recent-pages",
]);

const IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/;
// An event in the contract: a lowercase channel name.
const EVENT = /^[a-z_][A-Za-z0-9_]*$/;

class Fail extends Error {
  error: UnitError;
  constructor(error: UnitError) {
    super(error.message);
    this.error = error;
  }
}

export function loadUnit(src: string): { ok: true; unit: Unit } | { ok: false; errors: UnitError[] } {
  const lines = new LineCounter();
  const doc = parseDocument(src, { lineCounter: lines, uniqueKeys: true, prettyErrors: false, version: "1.2" });
  const pos = (offset: number): At => {
    const p = lines.linePos(offset);
    return { line: Math.max(p.line, 1), col: p.col };
  };
  if (doc.errors.length) {
    return {
      ok: false,
      errors: doc.errors.map((e) => ({ ...pos(e.pos[0]), path: "", message: e.message.split("\n")[0] })),
    };
  }
  const at = (n: Node | null | undefined): At => (n?.range ? pos(n.range[0]) : { line: 1, col: 1 });
  const fail = (n: Node | null | undefined, path: string, message: string): never => {
    throw new Fail({ ...at(n), path, message });
  };

  // Data only: no anchors, aliases or tags.
  let refused: UnitError | null = null;
  visit(doc, {
    Alias(_, n) {
      refused ??= { ...at(n), path: "", message: "aliases aren't allowed; the unit is plain data" };
    },
    Node(_, n) {
      if (n.anchor) refused ??= { ...at(n), path: "", message: "anchors aren't allowed; the unit is plain data" };
      if (n.tag && !isMap(n) && !isSeq(n)) refused ??= { ...at(n), path: "", message: `tags such as ${n.tag} aren't allowed` };
    },
  });
  if (refused) return { ok: false, errors: [refused] };

  try {
    const fields = (n: unknown, path: string, required: string[], optional: string[]) => {
      if (!isMap(n)) fail(n as Node, path, "expected a mapping");
      const map = n as import("yaml").YAMLMap<unknown, unknown>;
      const out = new Map<string, { key: Node; value: Node | null }>();
      for (const item of map.items) {
        const key = item.key as Node;
        if (!isScalar(key) || typeof key.value !== "string") fail(key, path, "keys must be strings");
        const name = (key as import("yaml").Scalar<string>).value;
        if (![...required, ...optional].includes(name)) {
          fail(key, path, `unknown field ${name} (expected ${[...required, ...optional].join(", ")})`);
        }
        out.set(name, { key, value: item.value as Node | null });
      }
      for (const r of required) if (!out.has(r)) fail(map, path, `missing field ${r}`);
      return out;
    };
    const str = (n: Node | null, path: string): string => {
      if (!isScalar(n) || typeof n.value !== "string") {
        const got = isScalar(n) ? (n.value === null ? "nothing" : `a ${typeof n.value}`) : "a collection";
        return fail(n, path, `expected a string, got ${got}${isScalar(n) && n.value !== null ? " (quote it)" : ""}`);
      }
      return n.value;
    };
    const list = (n: Node | null, path: string): { value: string; node: Node }[] => {
      if (!isSeq(n)) fail(n, path, "expected a list");
      return (n as import("yaml").YAMLSeq<Node>).items.map((item, i) => ({ value: str(item, `${path}[${i}]`), node: item }));
    };
    const uint = (n: Node | null, path: string): number => {
      if (!isScalar(n) || typeof n.value !== "number" || !Number.isInteger(n.value) || n.value < 0) {
        fail(n, path, "expected a non-negative integer");
      }
      return (n as import("yaml").Scalar<number>).value;
    };

    const top = fields(doc.contents, "", ["translate"], ["hidden"]);
    const t = fields(top.get("translate")!.value, "translate", ["tools", "rules"], [
      "schema",
      "assumption",
      "fallback",
      "timeoutMs",
      "unroll",
    ]);

    const tools: string[] = [];
    for (const { value, node } of list(t.get("tools")!.value, "translate.tools")) {
      if (!NOTION_TOOLS.has(value)) fail(node, "translate.tools", `${value} is not one of Notion's tools`);
      if (tools.includes(value)) fail(node, "translate.tools", `${value} is listed twice`);
      tools.push(value);
    }
    if (!tools.length) fail(t.get("tools")!.value, "translate.tools", "name at least one tool");

    const schema: Field[] = [];
    const s = t.get("schema");
    if (s && s.value !== null) {
      if (!isMap(s.value)) fail(s.value, "translate.schema", "expected a mapping of argument: type");
      for (const item of (s.value as import("yaml").YAMLMap<Node, Node>).items) {
        const name = str(item.key, "translate.schema");
        const path = `translate.schema.${name}`;
        if (!IDENT.test(name)) fail(item.key, path, "an argument name must be an identifier");
        if (name === "tool") fail(item.key, path, "tool is the called tool's name, declared for you");
        const type = str(item.value, path);
        const ty = parseType(type);
        if (typeof ty === "string") fail(item.value, path, ty);
        schema.push({ name, type, ty: ty as Ty });
      }
    }

    const a = t.get("assumption");
    const assumption = a ? str(a.value, "translate.assumption") : "";

    const rules: Rule[] = [];
    const r = t.get("rules")!.value;
    if (!isMap(r)) fail(r, "translate.rules", "expected a mapping of rule name to { when, emit }");
    for (const item of (r as import("yaml").YAMLMap<Node, Node>).items) {
      const name = str(item.key, "translate.rules");
      const path = `translate.rules.${name}`;
      if (!IDENT.test(name)) fail(item.key, path, "a rule name must be an identifier");
      const f = fields(item.value, path, ["when", "emit"], []);
      const whenNode = f.get("when")!.value;
      const when = str(whenNode, `${path}.when`);
      if (!when.trim()) fail(whenNode, `${path}.when`, "empty predicate");
      const emitNode = f.get("emit")!.value;
      const emit = str(emitNode, `${path}.emit`);
      if (!EVENT.test(emit)) fail(emitNode, `${path}.emit`, `${emit} isn't an event name (lowercase, like draft)`);
      rules.push({ name, when, emit, at: at(whenNode) });
    }
    if (!rules.length) fail(r, "translate.rules", "write at least one rule");

    let fallback = "other";
    for (let i = 2; rules.some((x) => x.emit === fallback); i++) fallback = `other_${i}`;
    const fb = t.get("fallback");
    if (fb) {
      const f = fields(fb.value, "translate.fallback", ["emit"], []);
      const node = f.get("emit")!.value;
      fallback = str(node, "translate.fallback.emit");
      if (!EVENT.test(fallback)) fail(node, "translate.fallback.emit", `${fallback} isn't an event name`);
      const clash = rules.find((x) => x.emit === fallback);
      if (clash) fail(node, "translate.fallback.emit", `rule ${clash.name} also emits ${fallback}; the fallback must be a distinct event`);
    }

    const hidden: string[] = [];
    const h = top.get("hidden");
    if (h) {
      for (const { value, node } of list(h.value, "hidden")) {
        if (!NOTION_TOOLS.has(value)) fail(node, "hidden", `${value} is not one of Notion's tools`);
        if (!NOTION_READ_ONLY.has(value)) fail(node, "hidden", `${value} isn't reviewed as read-only, so it can't skip the contract`);
        if (tools.includes(value)) fail(node, "hidden", `${value} is translated, so it can't also be hidden`);
        hidden.push(value);
      }
    }

    const timeout = t.get("timeoutMs");
    const timeoutMs = timeout ? uint(timeout.value, "translate.timeoutMs") : 10_000;
    if (timeoutMs === 0) fail(timeout!.value, "translate.timeoutMs", "must be positive");
    const unrollNode = t.get("unroll");
    const unroll = unrollNode ? uint(unrollNode.value, "translate.unroll") : 5;

    return {
      ok: true,
      unit: { tools, schema, assumption, assumptionAt: a ? at(a.value) : undefined, rules, fallback, hidden, timeoutMs, unroll },
    };
  } catch (e) {
    if (e instanceof Fail) return { ok: false, errors: [e.error] };
    throw e;
  }
}
